DROP TABLE IF EXISTS `iot_alert_record`;

CREATE TABLE `iot_alert_record` (
  `alert_id` bigint(20) NOT NULL COMMENT '告警ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `rule_id` bigint(20) DEFAULT NULL COMMENT '命中规则ID(空=YAML兜底默认或EWMA异常)',
  `source` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RULE' COMMENT '来源: RULE/DEFAULT/ANOMALY',
  `device_id` bigint(20) NOT NULL COMMENT '设备ID',
  `device_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备编码(冗余)',
  `product_id` bigint(20) NOT NULL DEFAULT '0' COMMENT '产品ID(冗余)',
  `property_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '属性编码',
  `alert_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OTHER' COMMENT '告警类型: TEMPERATURE/VIBRATION/PRESSURE/OTHER/ANOMALY',
  `alert_level` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MEDIUM' COMMENT '告警级别: HIGH/MEDIUM/LOW',
  `compare_operator` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GT' COMMENT '比较符快照',
  `threshold` decimal(14,4) DEFAULT NULL COMMENT '阈值快照(用于恢复判定)',
  `trigger_value` decimal(14,4) DEFAULT NULL COMMENT '触发值(最近一次超限值)',
  `alert_message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '告警描述',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '状态机: ACTIVE/ACKNOWLEDGED/RESOLVED',
  `active_flag` tinyint(1) DEFAULT '1' COMMENT '未恢复标记(1=未恢复, NULL=已恢复); 唯一键组成',
  `trigger_time` datetime NOT NULL COMMENT '首次触发时间',
  `last_trigger_time` datetime DEFAULT NULL COMMENT '最近触发时间',
  `ack_time` datetime DEFAULT NULL COMMENT '确认时间',
  `ack_by` bigint(20) DEFAULT NULL COMMENT '确认人',
  `ack_remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '确认备注',
  `resolve_time` datetime DEFAULT NULL COMMENT '恢复时间',
  `resolve_by` bigint(20) DEFAULT NULL COMMENT '恢复操作人(空=系统自动恢复)',
  `resolve_value` decimal(14,4) DEFAULT NULL COMMENT '恢复值',
  `resolve_remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '恢复备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`alert_id`) USING BTREE,
  UNIQUE KEY `uk_active_alert` (`tenant_id`,`device_id`,`property_code`,`active_flag`) USING BTREE,
  KEY `idx_query` (`tenant_id`,`device_id`,`status`,`trigger_time`) USING BTREE,
  KEY `idx_status_time` (`tenant_id`,`status`,`trigger_time`) USING BTREE,
  KEY `idx_rule` (`rule_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IoT告警记录(含确认/恢复状态机)';

