DROP TABLE IF EXISTS `iot_alert_rule`;

CREATE TABLE `iot_alert_rule` (
  `rule_id` bigint(20) NOT NULL COMMENT '规则ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `rule_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '规则名称',
  `product_id` bigint(20) NOT NULL DEFAULT '0' COMMENT '产品范围(0=不限)',
  `device_id` bigint(20) NOT NULL DEFAULT '0' COMMENT '设备范围(0=不限)',
  `property_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '属性编码',
  `compare_operator` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GT' COMMENT '比较符: GT/GE/LT/LE/EQ/NE',
  `threshold` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '阈值',
  `duration_sec` int(11) NOT NULL DEFAULT '0' COMMENT '持续时长(秒): 超限持续该时长才告警, 0=立即告警',
  `debounce_sec` int(11) NOT NULL DEFAULT '60' COMMENT '去抖窗口(秒): 窗口内仅合并落库不重复推送',
  `alert_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OTHER' COMMENT '告警类型: TEMPERATURE/VIBRATION/PRESSURE/OTHER',
  `alert_level` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MEDIUM' COMMENT '告警级别: HIGH/MEDIUM/LOW',
  `notify_channels` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT 'SSE,MES_ANDON' COMMENT '通知渠道(逗号分隔): SSE/MES_ANDON',
  `enabled` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '启用状态(1启用 0停用)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`rule_id`) USING BTREE,
  UNIQUE KEY `uk_rule_scope` (`tenant_id`,`product_id`,`device_id`,`property_code`) USING BTREE,
  KEY `idx_tenant_property` (`tenant_id`,`property_code`,`enabled`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IoT告警规则';

