DROP TABLE IF EXISTS `iot_device_command`;

CREATE TABLE `iot_device_command` (
  `command_id` bigint(20) NOT NULL COMMENT '指令ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `device_id` bigint(20) NOT NULL COMMENT '设备ID',
  `device_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '设备编码(冗余)',
  `command_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PROPERTY_SET' COMMENT '指令类型: PROPERTY_SET/SERVICE_INVOKE',
  `topic` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '下发Topic',
  `payload` text COLLATE utf8mb4_unicode_ci COMMENT '下发载荷(JSON)',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '状态: PENDING/SENT/SUCCESS/FAILED/TIMEOUT',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '重发次数',
  `sent_time` datetime DEFAULT NULL COMMENT '下发时间',
  `ack_time` datetime DEFAULT NULL COMMENT '设备回执时间',
  `ack_payload` text COLLATE utf8mb4_unicode_ci COMMENT '设备回执载荷',
  `ack_msg_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '回执消息ID(幂等去重键)',
  `result_message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '下发/回执结果说明',
  `operator_id` bigint(20) DEFAULT NULL COMMENT '下发人',
  `operator_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '下发人名称',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`command_id`) USING BTREE,
  UNIQUE KEY `uk_ack_msg_id` (`ack_msg_id`) USING BTREE,
  KEY `idx_query` (`tenant_id`,`device_id`,`create_time`) USING BTREE,
  KEY `idx_status` (`tenant_id`,`status`,`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IoT下行指令(下发留痕+回执状态)';

