DROP TABLE IF EXISTS `iot_device_data`;

CREATE TABLE `iot_device_data` (
  `data_id` bigint(20) NOT NULL COMMENT '数据ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `device_id` bigint(20) NOT NULL COMMENT '设备ID',
  `device_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备编码(冗余)',
  `property_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '属性编码',
  `property_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '属性名称',
  `data_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据类型: NUMERIC/TEXT/BOOL',
  `numeric_value` decimal(14,4) DEFAULT NULL COMMENT '数值型值',
  `text_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文本型值',
  `bool_value` tinyint(1) DEFAULT NULL COMMENT '布尔型值(0/1)',
  `collect_time` datetime NOT NULL COMMENT '采集时间(设备侧)',
  `receive_time` datetime NOT NULL COMMENT '接收时间(服务端)',
  `quality` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'GOOD' COMMENT '数据质量: GOOD/BAD/UNCERTAIN',
  `source` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'MQTT' COMMENT '数据来源: MQTT/OPC_UA/MODBUS/HTTP',
  `source_msg_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源消息ID(Redis Stream entry id,幂等去重键)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`data_id`) USING BTREE,
  UNIQUE KEY `uk_source_msg_id` (`source_msg_id`) USING BTREE,
  KEY `idx_device_time` (`device_id`,`collect_time`) USING BTREE,
  KEY `idx_property` (`device_id`,`property_code`,`collect_time`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IoT设备数据(原始)';

