DROP TABLE IF EXISTS `iot_device_event`;

CREATE TABLE `iot_device_event` (
  `event_id` bigint(20) NOT NULL COMMENT '事件ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `device_id` bigint(20) NOT NULL COMMENT '设备ID',
  `device_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备编码(冗余)',
  `product_id` bigint(20) DEFAULT NULL COMMENT '产品ID(冗余)',
  `event_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '事件编码',
  `event_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '事件名称(设备上报)',
  `event_level` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '事件级别: INFO/WARN/ERROR/CRITICAL(设备上报)',
  `event_time` datetime NOT NULL COMMENT '事件发生时间(设备侧)',
  `receive_time` datetime DEFAULT NULL COMMENT '服务端接收时间',
  `payload` text COLLATE utf8mb4_unicode_ci COMMENT '事件原始载荷(JSON)',
  `quality` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'GOOD' COMMENT '数据质量: GOOD/BAD/UNCERTAIN',
  `process_status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '处理状态: PENDING/PROCESSED/IGNORED/FAILED',
  `process_remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理说明',
  `alert_id` bigint(20) DEFAULT NULL COMMENT '联动生成的告警ID(空=未联动)',
  `source` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'MQTT' COMMENT '数据来源: MQTT/HTTP',
  `source_msg_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源消息ID(Redis Stream entry id,幂等去重键)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`event_id`) USING BTREE,
  UNIQUE KEY `uk_source_msg_id` (`source_msg_id`) USING BTREE,
  KEY `idx_query` (`tenant_id`,`device_id`,`event_time`) USING BTREE,
  KEY `idx_status` (`tenant_id`,`process_status`,`event_time`) USING BTREE,
  KEY `idx_code` (`tenant_id`,`event_code`,`event_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IoT设备事件上报(含处理状态与告警联动)';

