DROP TABLE IF EXISTS `iot_device_group_rel`;

CREATE TABLE `iot_device_group_rel` (
  `rel_id` bigint(20) NOT NULL COMMENT '关系ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
