DROP TABLE IF EXISTS `iot_firmware`;

CREATE TABLE `iot_firmware` (
  `firmware_id` bigint(20) NOT NULL COMMENT '固件ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `firmware_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '固件名称',
  `product_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '适用产品型号(iot_product.product_code,空=不限)',
  `hardware_model` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '适用硬件型号(空=不限,仅登记不参与匹配)',
  `version` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '版本号',
  `file_oss_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '固件包OSS文件ID',
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '固件包文件名',
  `file_size` bigint(20) NOT NULL DEFAULT '0' COMMENT '固件包大小(字节)',
  `checksum_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MD5' COMMENT '校验算法: MD5/SHA256',
  `checksum` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '校验值(小写十六进制)',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT '发布状态: DRAFT/RELEASED/DISABLED',
  `release_time` datetime DEFAULT NULL COMMENT '发布时间',
  `change_log` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更说明',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志(0正常 1删除)',
  PRIMARY KEY (`firmware_id`) USING BTREE,
  UNIQUE KEY `uk_version` (`tenant_id`,`product_key`,`version`) USING BTREE,
  KEY `idx_status` (`tenant_id`,`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IoT固件登记(版本/包/校验值/发布状态)';

