DROP TABLE IF EXISTS `iot_forward_log`;

CREATE TABLE `iot_forward_log` (
  `log_id` bigint(20) NOT NULL COMMENT '日志ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `rule_id` bigint(20) NOT NULL COMMENT '转发规则ID',
  `device_id` bigint(20) NOT NULL COMMENT '设备ID',
  `device_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备编码(冗余)',
  `property_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '属性编码',
  `target_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实际投递URL',
  `payload` text COLLATE utf8mb4_unicode_ci COMMENT '投递载荷(JSON)',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '状态: PENDING/SUCCESS/FAILED',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '已重试次数',
  `http_status` int(11) DEFAULT NULL COMMENT 'HTTP响应码',
  `error_msg` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败原因',
  `next_retry_time` datetime DEFAULT NULL COMMENT '下次重试时间(空=不再重试)',
  `last_attempt_time` datetime DEFAULT NULL COMMENT '最近一次投递时间',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`log_id`) USING BTREE,
  KEY `idx_retry` (`tenant_id`,`status`,`next_retry_time`) USING BTREE,
  KEY `idx_rule` (`rule_id`) USING BTREE,
  KEY `idx_device` (`tenant_id`,`device_id`,`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IoT数据转发投递留痕(失败可重试)';

