DROP TABLE IF EXISTS `iot_forward_rule`;

CREATE TABLE `iot_forward_rule` (
  `rule_id` bigint(20) NOT NULL COMMENT '规则ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `rule_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '规则名称',
  `product_id` bigint(20) NOT NULL DEFAULT '0' COMMENT '产品范围(0=不限)',
  `device_id` bigint(20) NOT NULL DEFAULT '0' COMMENT '设备范围(0=不限)',
  `property_codes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '属性编码白名单(逗号分隔,空=全部)',
  `target_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'HTTP' COMMENT '目标类型: HTTP',
  `target_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'Webhook URL(仅http/https, 内网/保留地址被拒)',
  `http_method` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'POST' COMMENT 'HTTP方法: POST/PUT',
  `headers` text COLLATE utf8mb4_unicode_ci COMMENT '自定义请求头(JSON)',
  `timeout_ms` int(11) NOT NULL DEFAULT '5000' COMMENT '单次投递超时(毫秒)',
  `max_retry` int(11) NOT NULL DEFAULT '3' COMMENT '最大重试次数',
  `enabled` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '启用状态(1启用 0停用)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`rule_id`) USING BTREE,
  UNIQUE KEY `uk_rule_scope` (`tenant_id`,`product_id`,`device_id`,`rule_name`) USING BTREE,
  KEY `idx_enabled` (`tenant_id`,`enabled`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IoT数据转发规则(HTTP Webhook)';

INSERT INTO `iot_forward_rule` (`rule_id`, `tenant_id`, `rule_name`, `product_id`, `device_id`, `property_codes`, `target_type`, `target_url`, `http_method`, `headers`, `timeout_ms`, `max_retry`, `enabled`, `remark`, `create_dept`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES
