DROP TABLE IF EXISTS `iot_ota_task`;

CREATE TABLE `iot_ota_task` (
  `task_id` bigint(20) NOT NULL COMMENT '升级任务ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `firmware_id` bigint(20) NOT NULL COMMENT '固件ID(iot_firmware)',
  `target_version` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '目标版本(冗余,固件删除后仍可追溯)',
  `current_version` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '下发时设备当前版本',
  `device_id` bigint(20) NOT NULL COMMENT '目标设备ID',
  `device_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '设备编码(冗余)',
  `group_id` bigint(20) DEFAULT NULL COMMENT '来源分组ID(按分组批量下发时记录)',
  `batch_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批量下发批次号',
  `command_id` bigint(20) DEFAULT NULL COMMENT '关联下行指令ID(iot_device_command,下发留痕)',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '状态: PENDING/SENT/UPGRADING/SUCCESS/FAILED/TIMEOUT/CANCELLED',
  `progress` int(11) NOT NULL DEFAULT '0' COMMENT '升级进度(0-100)',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '人工重试次数',
  `sent_time` datetime DEFAULT NULL COMMENT '指令下发时间',
  `start_time` datetime DEFAULT NULL COMMENT '设备开始升级时间',
  `finish_time` datetime DEFAULT NULL COMMENT '结束时间',
  `fail_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败/取消原因',
  `report_msg_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近一次回执的消息ID(Stream entry id,便于取证)',
  `operator_id` bigint(20) DEFAULT NULL COMMENT '下发人',
  `operator_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '下发人名称',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`task_id`) USING BTREE,
  KEY `idx_device` (`tenant_id`,`device_id`,`create_time`) USING BTREE,
  KEY `idx_status` (`tenant_id`,`status`,`sent_time`) USING BTREE,
  KEY `idx_firmware` (`tenant_id`,`firmware_id`) USING BTREE,
  KEY `idx_batch` (`batch_no`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IoT OTA固件升级任务(单设备/按分组批量)';

